import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Color
  } = THREE;

  const root = new Group();
  root.name = 'features-card-2';

  const region = config.atlasRegion ?? {
    x: 0,
    y: 0,
    width: 512,
    height: 320,
    atlasWidth: 512,
    atlasHeight: 320
  };

  const atlasWidth = region.atlasWidth ?? 512;
  const atlasHeight = region.atlasHeight ?? 320;
  const aspect = region.width / region.height;
  const width = 1.72;
  const height = width / aspect;

  const resources = [];
  const timelines = [];
  const cleanups = [];
  let disposed = false;

  const gradientMaterial = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'),
    roughness: 0.72
  });

  gradientMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.043, 0.043, 0.063),
      smoothstep(0.12, 0.92, uv().y)
    ),
    smoothstep(0.0, 1.0, uv().x)
  );

  const backingGeometry = new PlaneGeometry(width, height);
  const backing = new Mesh(backingGeometry, gradientMaterial);
  backing.name = 'engineered-gradient-surface';
  backing.position.z = -0.035;
  root.add(backing);
  resources.push(backingGeometry, gradientMaterial);

  const imageMaterial = new MeshBasicNodeMaterial({
    color: new Color('#e8ecf2'),
    transparent: true,
    opacity: 0.98,
    depthWrite: false
  });

  const imageGeometry = new PlaneGeometry(width, height);
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.name = 'atlas-sprite';
  imagePlane.position.z = 0.025;
  root.add(imagePlane);
  resources.push(imageGeometry, imageMaterial);

  const borderMaterial = new MeshBasicNodeMaterial({
    color: new Color('#ff2a38'),
    transparent: true,
    opacity: 0.88
  });

  const railThickness = 0.018;
  const railDepth = 0.026;
  const rails = [
    [width + railThickness, railThickness, 0, height * 0.5, 0.055],
    [width + railThickness, railThickness, 0, -height * 0.5, 0.055],
    [railThickness, height * 0.72, -width * 0.5, height * 0.14, 0.055]
  ];

  for (const [railWidth, railHeight, x, y, z] of rails) {
    const geometry = new BoxGeometry(railWidth, railHeight, railDepth);
    const rail = new Mesh(geometry, borderMaterial);
    rail.position.set(x, y, z);
    rail.name = 'signal-red-machining-rail';
    root.add(rail);
    resources.push(geometry);
  }
  resources.push(borderMaterial);

  const detailMaterial = new MeshBasicNodeMaterial({
    color: new Color('#e8ecf2'),
    transparent: true,
    opacity: 0.34
  });

  const detailGeometry = new BoxGeometry(width * 0.34, 0.012, 0.018);
  const detail = new Mesh(detailGeometry, detailMaterial);
  detail.name = 'paper-detail-line';
  detail.position.set(-width * 0.22, -height * 0.34, 0.065);
  root.add(detail);
  resources.push(detailGeometry, detailMaterial);

  const dotGeometry = new BoxGeometry(0.035, 0.035, 0.022);
  const dot = new Mesh(dotGeometry, borderMaterial);
  dot.name = 'signal-red-index';
  dot.position.set(width * 0.34, height * 0.31, 0.07);
  root.add(dot);
  resources.push(dotGeometry);

  root.onBeforeRender = (_renderer, camera) => {
    if (!disposed && camera) {
      root.quaternion.copy(camera.quaternion);
    }
  };

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) return;

      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = THREE.ClampToEdgeWrapping;
      texture.wrapT = THREE.ClampToEdgeWrapping;
      texture.repeat.set(
        region.width / atlasWidth,
        region.height / atlasHeight
      );
      texture.offset.set(
        region.x / atlasWidth,
        1 - (region.y + region.height) / atlasHeight
      );
      texture.needsUpdate = true;

      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    });
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    for (const cleanup of cleanups) {
      if (typeof cleanup === 'function') cleanup();
    }

    root.traverse((object) => {
      if (object.geometry && typeof object.geometry.dispose === 'function') {
        object.geometry.dispose();
      }

      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];

        for (const material of materials) {
          if (material && typeof material.dispose === 'function') {
            material.dispose();
          }
        }
      }
    });

    root.onBeforeRender = null;
  };

  return root;
}
